// Generated by monolith-origin-export. Only hash-pinned shell assets are cached.
const CACHE = 'qikvrt-origin-__SHELL_ID__';
const ASSETS = __SHELL_ASSETS__;
const hex = bytes => Array.from(new Uint8Array(bytes),b=>b.toString(16).padStart(2,'0')).join('');
self.addEventListener('install',event=>event.waitUntil((async()=>{
  const alreadyPresent=await caches.has(CACHE);
  try {
    const verified=[];
    for (const [path,digest] of Object.entries(ASSETS)) {
      const url=new URL(path,self.registration.scope),response=await fetch(url,{cache:'no-store',credentials:'same-origin'});
      if (!response.ok || response.redirected || new URL(response.url).origin !== self.location.origin ||
          hex(await crypto.subtle.digest('SHA-256',await response.clone().arrayBuffer())) !== digest) throw Error('SHELL_BYTES_MISMATCH');
      verified.push([url,response]);
    }
    const cache=await caches.open(CACHE);
    for(const [url,response] of verified)await cache.put(url,response);
    await self.skipWaiting();
  } catch(error) {if(!alreadyPresent)await caches.delete(CACHE);throw error;}
})()));
self.addEventListener('activate',event=>event.waitUntil(self.clients.claim()));
self.addEventListener('message',event=>{if(event.data?.type==='QIKVRT_ORIGIN_READY')event.ports[0]?.postMessage({cache:CACHE,scope:self.registration.scope});});
self.addEventListener('fetch',event=>{
  if(event.request.method!=='GET')return;
  const url=new URL(event.request.url),base=new URL(self.registration.scope);
  if(url.origin!==base.origin || !url.pathname.startsWith(base.pathname))return;
  const relative=url.pathname.slice(base.pathname.length) || 'index.html';
  if(!Object.hasOwn(ASSETS,relative))return; // Never cache API responses, imports or private store bytes.
  event.respondWith((async()=>{
    const cached=await (await caches.open(CACHE)).match(new URL(relative,base));
    if(!cached)return new Response('Offline-Bootstrap unvollständig',{status:503});
    if(hex(await crypto.subtle.digest('SHA-256',await cached.clone().arrayBuffer()))!==ASSETS[relative])return new Response('Bootstrap-Prüfsumme weicht ab',{status:503});
    return cached;
  })());
});
